#!/usr/bin/env python3
"""Render .github/kcresize.json for the lab from lab.env values (used by: ./lab/setup.sh config).

usage: render-config.py <owner_github> <owner_email> <actioning_github> <actioning_email> <approval_label>
Comma-separated lists are allowed for every person field (users or @org/team).
"""
import json
import sys

owner, owner_email, act, act_email, label = (sys.argv[1:] + [""] * 5)[:5]


def lst(v):
    return [x.strip() for x in v.split(",") if x.strip()]


team = {"github": lst(owner), "email": lst(owner_email)}
cfg = {
    "_comment": "Generated by lab/setup.sh config from lab/lab.env. Cluster id and Kubecost URL come from repo "
                "variables KUBECOST_CLUSTER / KUBECOST_URL. Secrets go in repository secrets, never here.",
    "kubecost": {"window": "48h", "allocationWindow": "7d"},
    "scope": {"namespaces": [], "namespaceLabel": label or "kcresize.io/approval=required",
              "exclude": ["kube-system", "kube-public", "kube-node-lease", "kubecost", "local-path-storage", "objectstore"]},
    "owners": {ns: team for ns in ("tbm-payments", "shop-prod", "shop-dev")},
    "actioning": {"github": lst(act or owner), "email": lst(act_email or owner_email)},
    "notify": {"owner": ["email"], "actioning": ["email"]},
    "state": "github",
}
print(json.dumps(cfg, indent=2))
